        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate basic inputs
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    if (start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    if (sx < 0 || sx >= n || sy < 0 || sy >= n ||
        ex < 0 || ex >= n || ey < 0 || ey >= n) {
        return "cannot be travelled";
    }
    // If start equals end, path exists trivially
    if (sx == ex && sy == ey) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    java.util.function.Consumer<int[]> addEdge = (int[] p) -> {
        if (p == null || p.length != 4) return;
        int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n ||
            x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
            return;
        }
        String a = x1 + "," + y1;
        String b = x2 + "," + y2;
        graph.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        graph.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    };
    for (int[] path : paths) {
        addEdge.accept(path);
    }

    // BFS
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    String startKey = sx + "," + sy;
    String endKey = ex + "," + ey;
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = graph.get(cur);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                if (nb.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return "Invalid date";
    }
    try {
        java.time.format.DateTimeFormatter parser = java.time.format.DateTimeFormatter.ofPattern("M d yyyy");
        java.time.LocalDate localDate = java.time.LocalDate.parse(date, parser);
        java.time.format.DateTimeFormatter formatter = java.time.format.DateTimeFormatter.ofPattern("MMMM d, yyyy");
        String formattedDate = localDate.format(formatter);
        java.time.DayOfWeek dayOfWeek = localDate.getDayOfWeek();
        String weekday = dayOfWeek.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        return formattedDate + " is a " + weekday;
    } catch (Exception e) {
        return "Invalid date";
    }
}

public int[] twoSum(int[] nums, int target) {
    if (nums == null || nums.length < 2) {
        return new int[0];
    }
    java.util.Map<Integer, Integer> map = new java.util.HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (map.containsKey(complement)) {
            return new int[]{map.get(complement), i};
        }
        // Store the index of the current number
        // If the same number appears again, we keep the first index
        if (!map.containsKey(nums[i])) {
            map.put(nums[i], i);
        }
    }
    // According to the problem statement, there should always be a solution.
    // Return an empty array if none is found (defensive programming).
    return new int[0];
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is sorted
        if (nums[left] <= nums[mid]) { // left side is sorted
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else { // right side is sorted
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int n = arr.length;
    int k = n / 20; // number of elements to trim from each side
    if (k == 0) {
        // If k is zero, simply return the mean of all elements
        long total = 0;
        for (int val : arr) {
            total += val;
        }
        return total / (double) n;
    }
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += sorted[i];
    }
    int remaining = n - 2 * k;
    return sum / (double) remaining;
}

public boolean canArrange(int[] arr, int k) {
    // Validate input
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    // Must be even length to form pairs
    if (n % 2 != 0) {
        return false;
    }
    // Frequency array for remainders
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // ensure non-negative remainder
        freq[r]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, check remainder k/2
    if (k % 2 == 0) {
        int half = k / 2;
        if (freq[half] % 2 != 0) {
            return false;
        }
    }
    // Check other remainders
    int upper = k / 2;
    for (int r = 1; r <= upper; r++) {
        if (r == k - r) { // already handled when k even
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) return 0;
    if (edges == null || edges.length != n - 1) {
        throw new IllegalArgumentException("Edges array must have n-1 elements.");
    }
    if (hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("hasApple array length must be n.");
    }

    // Build adjacency list
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }
    for (int[] e : edges) {
        if (e == null || e.length != 2) {
            throw new IllegalArgumentException("Each edge must contain exactly two nodes.");
        }
        int u = e[0], v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            throw new IllegalArgumentException("Edge node indices out of bounds.");
        }
        adj[u].add(v);
        adj[v].add(u);
    }

    boolean[] hasAppleSubtree = new boolean[n];
    int total = 0;

    // Stack for iterative DFS: {node, parent, state}
    // state 0 = pre-visit, 1 = post-visit
    Deque<int[]> stack = new ArrayDeque<>();
    stack.push(new int[]{0, -1, 0});

    while (!stack.isEmpty()) {
        int[] cur = stack.pop();
        int node = cur[0];
        int parent = cur[1];
        int state = cur[2];

        if (state == 0) {
            // Pre-visit: push post-visit marker
            stack.push(new int[]{node, parent, 1});
            // Push children
            for (int nei : adj[node]) {
                if (nei == parent) continue;
                stack.push(new int[]{nei, node, 0});
            }
        } else {
            // Post-visit: compute hasAppleSubtree and accumulate cost
            boolean hasAppleHere = hasApple[node];
            for (int nei : adj[node]) {
                if (nei == parent) continue;
                if (hasAppleSubtree[nei]) {
                    hasAppleHere = true;
                    total += 2; // go to child and back
                }
            }
            hasAppleSubtree[node] = hasAppleHere;
        }
    }

    return total;
}

public String sortString(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int[] count = new int[26];
    for (char ch : s.toCharArray()) {
        if (ch < 'a' || ch > 'z') {
            throw new IllegalArgumentException("Input string must contain only lowercase letters a-z");
        }
        count[ch - 'a']++;
    }
    StringBuilder result = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                remaining--;
            }
        }
        // Descending pass
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                remaining--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    Set<Long>[] dp = new Set[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0L);
    for (int num : nums) {
        // iterate sizes in reverse to avoid using updated values in the same iteration
        for (int size = n - 1; size >= 1; size--) {
            if (!dp[size - 1].isEmpty()) {
                for (Long prevSum : dp[size - 1]) {
                    dp[size].add(prevSum + num);
                }
            }
        }
    }
    // Check for any valid split
    for (int k = 1; k <= n / 2; k++) {
        if ((long) totalSum * k % n != 0) {
            continue;
        }
        long target = ((long) totalSum * k) / n;
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("cost array must not be null or empty");
    }
    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int uniqueMorseRepresentations(String[] words) {
    // Standard Morse code mapping for letters a-z
    String[] morse = {
        ".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..", ".---",
        "-.-", ".-..", "--", "-.", "---", ".--.", "--.-", ".-.", "...", "-",
        "..-", "...-", ".--", "-..-", "-.--", "--.."
    };

    if (words == null || words.length == 0) {
        return 0;
    }

    java.util.Set<String> uniqueSet = new java.util.HashSet<>();

    for (String word : words) {
        if (word == null) {
            continue; // skip null entries
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            // Convert to lowercase to handle uppercase letters if present
            if (c >= 'A' && c <= 'Z') {
                c = (char) (c - 'A' + 'a');
            }
            if (c < 'a' || c > 'z') {
                // Skip characters that are not letters
                continue;
            }
            sb.append(morse[c - 'a']);
        }
        uniqueSet.add(sb.toString());
    }

    return uniqueSet.size();
}

public boolean hasAllCodes(String s, int k) {
    // Validate input
    if (s == null || k <= 0) {
        return true; // Empty string is trivially present for k <= 0
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    // Avoid overflow for large k
    if (k > 20) { // 2^20 = 1,048,576, which is a safe upper bound for typical constraints
        return false;
    }
    int totalCodes = 1 << k;
    boolean[] seen = new boolean[totalCodes];
    int mask = 0;
    int maskLimit = totalCodes - 1;
    int seenCount = 0;
    for (int i = 0; i < n; i++) {
        // Build the current k-bit window
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[mask]) {
                seen[mask] = true;
                seenCount++;
                if (seenCount == totalCodes) {
                    return true; // All codes found early
                }
            }
        }
    }
    return seenCount == totalCodes;
}

