public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    long maxEnding = 0, minEnding = 0;
    long maxSum = Long.MIN_VALUE, minSum = Long.MAX_VALUE;
    for (int num : nums) {
        maxEnding = Math.max(num, maxEnding + num);
        maxSum = Math.max(maxSum, maxEnding);
        minEnding = Math.min(num, minEnding + num);
        minSum = Math.min(minSum, minEnding);
    }
    long result = Math.max(maxSum, -minSum);
    return (int) result;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int sz = fib.size();
        int next = fib.get(sz - 1) + fib.get(sz - 2);
        if (next > k) {
            break;
        }
        fib.add(next);
    }
    // Greedy subtraction from largest to smallest
    int count = 0;
    int remaining = k;
    for (int i = fib.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fib.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            if (top != c && Character.toLowerCase(top) == Character.toLowerCase(c)) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    int[] maxCount = {0};
    java.util.HashSet<String> used = new java.util.HashSet<>();
    dfs(s, 0, used, 0, maxCount);
    return maxCount[0];
}

private void dfs(String s, int index, java.util.Set<String> used, int count, int[] maxCount) {
    int n = s.length();
    if (index == n) {
        if (count > maxCount[0]) {
            maxCount[0] = count;
        }
        return;
    }
    for (int i = index; i < n; i++) {
        String sub = s.substring(index, i + 1);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(s, i + 1, used, count + 1, maxCount);
            used.remove(sub);
        }
    }
}

