public String getSmallestString(int n, int k) {
    // Validate input: each character contributes at least 1 and at most 26
    if (n <= 0 || k < n || k > 26 * n) {
        return "";
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        int remainingPositions = n - i - 1;
        // Find the smallest value for this position
        for (int v = 1; v <= 26; v++) {
            int remainingSum = k - v;
            if (remainingSum < remainingPositions) {
                // Even with all 'a's we cannot reach the required sum
                continue;
            }
            if (remainingSum > remainingPositions * 26) {
                // Even with all 'z's we cannot reach the required sum
                continue;
            }
            // This value works
            sb.append((char) ('a' + v - 1));
            k -= v;
            break;
        }
    }
    return sb.toString();
}

