    int result = 0;
    for (int i = 0; i < 32; i++) {
        int sum = 0;
        for (int num : nums) {
            sum += (num >> i) & 1;
        }
        if ((sum % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    // Handle 0 separately
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    // Start BFS from digits 1 to 9
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        int lastDigit = (int) (num % 10);
        // Next possible digits
        if (lastDigit > 0) {
            long nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
        if (lastDigit < 9) {
            long nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        count += higher * factor;
        if (cur == 1) {
            count += lower + 1;
        } else if (cur > 1) {
            count += factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A number is a power of two if it is positive and has exactly one bit set.
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    if (n == 0) {
        return 0;
    }
    // Validate that all rows are non-null and of equal length
    for (int i = 0; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            return 0;
        }
    }

    int[][] dpH = new int[m][n];   // horizontal
    int[][] dpV = new int[m][n];   // vertical
    int[][] dpD = new int[m][n];   // diagonal (top-left to bottom-right)
    int[][] dpAD = new int[m][n];  // anti-diagonal (top-right to bottom-left)

    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dpH[i][j] = (j > 0 ? dpH[i][j - 1] : 0) + 1;
                dpV[i][j] = (i > 0 ? dpV[i - 1][j] : 0) + 1;
                dpD[i][j] = (i > 0 && j > 0 ? dpD[i - 1][j - 1] : 0) + 1;
                dpAD[i][j] = (i > 0 && j < n - 1 ? dpAD[i - 1][j + 1] : 0) + 1;

                int currentMax = Math.max(
                        Math.max(dpH[i][j], dpV[i][j]),
                        Math.max(dpD[i][j], dpAD[i][j])
                );
                if (currentMax > maxLen) {
                    maxLen = currentMax;
                }
            } else {
                dpH[i][j] = 0;
                dpV[i][j] = 0;
                dpD[i][j] = 0;
                dpAD[i][j] = 0;
            }
        }
    }

    return maxLen;
}

public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }

    // Determine if the number is negative and work with its absolute value as a long
    boolean negative = n < 0;
    long absValue = negative ? -(long) n : n;

    String numStr = Long.toString(absValue);
    StringBuilder sb = new StringBuilder();

    int count = 0;
    for (int i = numStr.length() - 1; i >= 0; i--) {
        sb.append(numStr.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }

    sb.reverse();
    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;
    // Precompute perfect squares up to 2 * max(A)
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    // Sort to handle duplicates
    java.util.Arrays.sort(A);
    int fullMask = (1 << n) - 1;
    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();
    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int mask, int lastIdx) {
            long key = (((long) mask) << 32) | (lastIdx & 0xffffffffL);
            Integer cached = memo.get(key);
            if (cached != null) return cached;
            if (mask == fullMask) {
                return 1;
            }
            int count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                if (lastIdx != -1 && !isSquare[A[i] + A[lastIdx]]) continue;
                // Skip duplicates: if current value equals previous and previous not used
                if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
                count += applyAsInt(mask | (1 << i), i);
            }
            memo.put(key, count);
            return count;
        }
    };
    return dfs.applyAsInt(0, -1);
}

