public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    long maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int curHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && curHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    if (n == 0) {
        return new int[0];
    }
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        for (int i = 0; i < m; i++) {
            int j = sum - i;
            if (j >= 0 && j < n) {
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[] arr = new char[n];
    char[] digits = {'0', '1', '6', '8', '9'};
    Set<Character> selfRotating = new HashSet<>(Arrays.asList('0', '1', '8'));

    // Helper to get rotated character
    java.util.function.Function<Character, Character> rotate = c -> {
        switch (c) {
            case '0': return '0';
            case '1': return '1';
            case '8': return '8';
            case '6': return '9';
            case '9': return '6';
            default: return '?';
        }
    };

    // Backtracking function
    java.util.function.Consumer<Integer> backtrack = new java.util.function.Consumer<Integer>() {
        @Override
        public void accept(Integer pos) {
            if (pos >= (n + 1) / 2) {
                result.add(new String(arr));
                return;
            }
            for (char d : digits) {
                if (pos == 0 && n > 1 && d == '0') {
                    continue; // no leading zero for length > 1
                }
                if (n % 2 == 1 && pos == n - 1 - pos && !selfRotating.contains(d)) {
                    continue; // middle digit must be self-rotating
                }
                arr[pos] = d;
                arr[n - 1 - pos] = rotate.apply(d);
                accept(pos + 1);
            }
        }
    };

    backtrack.accept(0);
    return result;
}

